//! SFC (Serial Flash Controller) pad functions of the SWM341 pin matrix.
//!
//! Generated by `scripts/gen_pin_func.py` from the vendor header
//! `SWM341_port.h` -- do not edit by hand.
//!
//! The SFC only reaches the chip's dedicated Flash-SPI pads, D3..D8 of bank D;
//! they are not wired to SPI0/SPI1 in the pin matrix, so this table is the whole
//! story: one pad per signal, one function code per pad. Each `Pin{n}Func`
//! enumerates the FSPI functions selectable on pin `{n}`; the numeric value of
//! every variant is the 4-bit code written into `PORTx.FUNC0/FUNC1`. Code `0`
//! (generic GPIO) is omitted. Apply a variant with [`crate::gpio::set_function`]
//! after [`crate::gpio::acquire`].

/// Generate the per-pin `Pin{n}Func` enums for one bank module.
///
/// Each entry is `PinType => Enum { Variant = func_code, ... }`; the macro
/// writes the `#[repr(u8)]` enum plus its `PinFunc` / `PinFuncOf` impls.
/// The codes go into the `PinFunc::value` match instead of enum
/// discriminants: one pad often carries several names for the same line
/// (`LCD_CS` and `LCD_VSYNC` on PB2 are both code `6`), and two variants
/// with the same discriminant do not compile.
macro_rules! pad_funcs {
    ( $( $pin_ty:ident => $enum:ident { $( $var:ident = $val:literal ),* $(,)? } ),* $(,)? ) => {
        $(
            #[derive(Clone, Copy, PartialEq, Eq, Debug)]
            #[repr(u8)]
            pub enum $enum {
                $( $var, )*
            }
            impl crate::gpio::PinFunc for $enum {
                #[inline]
                fn value(self) -> u8 {
                    match self {
                        $( $enum::$var => $val, )*
                    }
                }
            }
            impl crate::gpio::PinFuncOf<crate::gpio::$pin_ty> for $enum {}
        )*
    };
}

pub mod d {
    pad_funcs! {
        PD3 => Pin3Func { FspiData2 = 2 },
        PD4 => Pin4Func { FspiData3 = 2 },
        PD5 => Pin5Func { FspiSclk = 1 },
        PD6 => Pin6Func { FspiSsel = 1 },
        PD7 => Pin7Func { FspiMiso = 3 },
        PD8 => Pin8Func { FspiMosi = 2 },
    }
}
